def render_htpasswd(users: list[dict], out_path: Path) -> int:
    """enabled 사용자만 user:hash 형태로 기록. 평문은 받지 않음."""
    lines: list[str] = []
    for u in users:
        if not u.get("enabled", True):
            continue
        # password_hash 는 이미 bcrypt/apr1 해시여야 함
        if not u.get("username"):
            raise ValueError("username missing")
        ...
        lines.append(f"{u['username']}:{u['password_hash']}")
    out_path.write_text("\n".join(lines) + "\n")
    out_path.chmod(0o640)
    return len(lines)

