import { linearRequest } from './client';
import { TEAM_ISSUES } from './queries';
import type { IssueNode, TeamIssuesResponse } from './types';

export interface PaginateOptions {
  teamId: string;
  updatedSince: string;
  pageSize?: number;
  /**
   * Sort field for subsequent pages. Linear's PaginationOrderBy only
   * supports createdAt | updatedAt.
   */
  sortField?: string;
}

const MAX_PAGES = 40;

export async function* paginateTeamIssues(
  opts: PaginateOptions,
): AsyncGenerator<IssueNode[], void, undefined> {
  const vars = {
    teamId: opts.teamId,
    first: opts.pageSize ?? 50,
    updatedSince: opts.updatedSince,
  };

  let cursor: string | null = null;
  let page = 0;

  while (page < MAX_PAGES) {
    const orderBy = page === 0 ? 'updatedAt' : opts.sortField ?? 'updatedAt';

    const res: TeamIssuesResponse = await linearRequest({
      operationName: 'TeamIssues',
      query: TEAM_ISSUES,
      variables: { ...vars, after: cursor, orderBy },
    });

    const conn = res.team.issues;
    yield conn.nodes;

    if (!conn.pageInfo.hasNextPage) return;
    cursor = conn.pageInfo.endCursor;
    page += 1;
  }
}

