{"stdout": "package com.example.orderapi.config;

import com.bugsnag.Bugsnag;
import com.bugsnag.EndpointConfiguration;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import lombok.Getter;
import lombok.Setter;

@Configuration
@Getter
@Setter
@ConfigurationProperties(prefix = "bugsnag")
public class BugsnagConfig {

    private String apiKey;
    private String endpointNotify;
    private String endpointSessions;
    private String releaseStage;
    private String[] notifyReleaseStages;
    private String appVersion;
    private String[] projectPackages;

    @Bean
    public Bugsnag bugsnag() {
        // notifyReleaseStages 에 포함되지 않은 stage 는 Bugsnag 이 조용히 전송을 건너뜀
        Bugsnag bugsnag = new Bugsnag(apiKey);
        bugsnag.setEndpoints(new EndpointConfiguration(endpointNotify, endpointSessions));
        bugsnag.setReleaseStage(releaseStage);
        bugsnag.setNotifyReleaseStages(notifyReleaseStages);
        bugsnag.setAppVersion(appVersion);
        bugsnag.setProjectPackages(projectPackages);
        return bugsnag;
    }
}
