19	/**
20	 * Build the HTX (Huobi) v2 signature.
21	 * https://huobiapi.github.io/docs/spot/v1/en/#authentication
22	 */
23	function signRequest(method, host, pathname, params, secret) {
24	  const all = {
25	    ...params,
26	    AccessKeyId: cfg.huobi.accessKeyId,
27	    SignatureMethod: 'HmacSHA256',
28	    SignatureVersion: '2',
29	    Timestamp: new Date().toISOString(),
30	  };
31	  const query = Object.keys(all)
32	    .map((k) => `${k}=${all[k]}`)
33	    .join('&');
34	  const payload = [method.toUpperCase(), host, pathname, query].join('\n');
35	  const signature = crypto.createHmac('sha256', secret).update(payload).digest('base64');
36	  return `${query}&Signature=${encodeURIComponent(signature)}`;
37	}
38	
39	async function huobi(method, pathname, params = {}, body = null) {
40	  const qs = signRequest(method, HUOBI_HOST, pathname, params, cfg.huobi.apiSecret);
41	  const url = `https://${HUOBI_HOST}${pathname}?${qs}`;
42	  const res = await axios({ method, url, data: body, timeout: 8000 });
43	  if (res.data.status === 'error') {
44	    const err = new Error(res.data['err-msg']);
45	    err.code = res.data['err-code'];
46	    throw err;
47	  }
48	  return res.data.data;
49	}
